#include <bits/stdc++.h>
using namespace std;
int main(){
    int T; cin>>T;
    while(T--){
        int N; cin>>N;
        vector<int> price(N), weight(N);
        for(int i=0;i<N;i++) cin>>price[i]>>weight[i];
        int G; cin>>G;
        long long total=0;
        for(int g=0; g<G; g++){
            int mw; cin>>mw;
            vector<int> dp(mw+1, 0);
            for(int i=0;i<N;i++){
                for(int c=mw; c>=weight[i]; c--){
                    dp[c] = max(dp[c], dp[c-weight[i]]+price[i]);
                }
            }
            total += dp[mw];
        }
        cout << total << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int T; cin>>T;
    while(T--){
        int N; cin>>N;
        vector<int> price(N), weight(N);
        for(int i=0;i<N;i++) cin>>price[i]>>weight[i];
        int G; cin>>G;
        vector<int> mws(G);
        for(int i=0;i<G;i++) cin>>mws[i];
        vector<int> order(G);
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a,int b){ return mws[a]>mws[b]; });
        vector<bool> used(N,false);
        long long total=0;
        for(int idx : order){
            int mw = mws[idx];
            vector<int> avail;
            for(int i=0;i<N;i++) if(!used[i]) avail.push_back(i);
            int n = (int)avail.size();
            vector<vector<int>> dp(n+1, vector<int>(mw+1,0));
            for(int i=1;i<=n;i++){
                int w=weight[avail[i-1]], p=price[avail[i-1]];
                for(int c=0;c<=mw;c++){
                    dp[i][c]=dp[i-1][c];
                    if(w<=c) dp[i][c]=max(dp[i][c], dp[i-1][c-w]+p);
                }
            }
            total += dp[n][mw];
            int c=mw;
            for(int i=n;i>=1;i--){
                if(dp[i][c]!=dp[i-1][c]){ used[avail[i-1]]=true; c-=weight[avail[i-1]]; }
            }
        }
        cout << total << "\n";
    }
}

